/**
 * Voice acting — maps a caption's EXACT text to its pre-generated audio file
 * (see MANIFEST.voice in assets.js, generated by tools/generate-voice.py).
 *
 * Only story captions carry a voice: the female protagonist (Ari), Prof.
 * Adeyemi, and the male storyteller who narrates the opening and closing.
 * Era cards, tutorial cards, hints, prompts, checkpoints and statistics stay
 * silent — if a caption's text is not in the table below, it simply is not
 * voiced. Lookup keys are normalised (case/punctuation-insensitive) so the
 * table matches the dialogue strings whatever typographic form they take.
 */

const norm = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const LINES = {
  // Prologue — the night of Field Test 7 (narrator + Ari)
  'chronos research facility 03 07 a m the night of field test 7': 'nar-intro',
  'professor adeyemi said to wait for her but the hourglass drive is stable just one more test': 'ari-wait',
  'drive at eighty percent a hundred all three cores holding': 'ari-eighty',
  'a hundred and twenty a hundred and forty shut it down shut it down': 'ari-shutdown',
  'no no no the cores': 'ari-cores',
  'the timeline shattered its three cores were flung across time into the distant past into this very night and into a far future': 'nar-shattered',
  // Wake-up in the Past
  'ugh where am i no when am i': 'ari-where',
  'the machine came with me but its sockets are empty': 'ari-machine',
  'if i can find all three cores i can put time back together that temple looks like a good place to start': 'ari-find',
  // Arrivals in the Present and the Future
  'it worked i m back in the lab no it s still that same night just after the accident': 'ari-lab',
  'the power s out and the second core is sealed in the vault i need answers and some light': 'ari-vault',
  'too far forward this is still the lab in the year 2187 the whole skyline is tearing itself apart': 'ari-2187',
  'the last core is up on that spire my gauntlet is humming i think i can dash through time now': 'ari-spire',
  // Epilogue — the next morning (narrator + Ari + the Professor)
  'morning the storm has passed': 'nar-morning',
  'all three cores back where they belong the hourglass is whole again': 'ari-whole',
  'ari the sensors went wild last night and then everything just settled what on earth happened down there': 'prof-sensors',
  'let s just say field test 7 was educational put the kettle on professor it s a long story': 'ari-kettle',
  'past present and future hum in harmony once more but time remembers every step you took': 'nar-harmony',
  // The Past — Ari's in-game lines (src/levels/ancientRuins.js)
  'two glowing plates by that gate and two heavy carved blocks if i push the blocks onto the plates maybe the gate will open': 'ari-plates',
  'it worked the gate is open there s sunlight pouring into the next court': 'ari-gate-open',
  'that beam comes through the round window if i turn those bronze mirrors i can bounce it onto the crystal by the cliff': 'ari-beam',
  'whoa stones are rising out of the chasm a bridge': 'ari-bridge',
  'a carving a symbol and a number this must be part of some kind of code': 'ari-tablet1',
  'that s all three tablets now i just need to find what they unlock': 'ari-tablets3',
  'three drums three hours i need the symbols from all three tablets to know how to set them': 'ari-altar-need',
  'three drums i ll set them to match the tablets hour i ii then iii': 'ari-altar-set',
  // The Present — Ari's in-game lines (src/levels/modernLab.js)
  'pitch black if the professor really wrote the code in phosphor ink my flashlight should pick it up': 'ari-ink',
  'the main power console if i can get the current flowing to the vault everything should come back on': 'ari-console',
  'power s back the vault should be open now east side of the hall': 'ari-powered',
};

const VOICED = new Map(Object.entries(LINES).map(([k, v]) => [norm(k), v]));

/** The pre-generated line key for a dialogue entry, or null when the entry is
 *  not voiced (non-caption views and unlisted texts stay silent). */
export function voiceKeyFor(entry) {
  if (!entry || entry.view !== 'caption' || !entry.text) return null;
  return VOICED.get(norm(entry.text)) || null;
}

/** True for Ari's own lines ('ari-*') — the ones that drive the close-up and
 *  the lip-sync in src/core/cinematic.js. */
export const isAriKey = (key) => !!key && key.startsWith('ari-');

export class Voice {
  constructor(audio) { this.audio = audio; }

  /** Play the line for a dialogue entry (captions only; anything else stays silent). */
  playFor(entry) {
    const key = voiceKeyFor(entry);
    if (!key) return;
    this.audio.playVoice(key);
  }

  /** Enter/click advanced past the line — cut it off immediately. */
  stop() { this.audio.stopVoice(); }
}
